def count_up_to(n):
    """Returns a list of prime numbers less than n."""
    if not isinstance(n, int):
        raise TypeError
    if n < 0:
        raise ValueError
    primes = []
    for num in range(2, n):
        is_prime = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

